package org.firstinspires.ftc.teamcode.opmodes.auto.generated;

import com.pedropathing.api.Paths;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.ivy.Command;
import com.pedropathing.math.Pose;
import com.pedropathing.paths.Path;
import com.pedropathing.paths.interpolator.Interpolator;

import org.firstinspires.ftc.teamcode.autokit.AutoKit;
import org.firstinspires.ftc.teamcode.autokit.AutoOption;

/**
 * Generated by the Auto Builder from r-three-tip-stream.pp. Do not edit: change the .pp and export again.
 */
public final class RThreeTipStreamAuto {

    private RThreeTipStreamAuto() {}

    /** The .pp file this was generated from. */
    public static final String SOURCE = "r-three-tip-stream.pp";

    /** When the .pp was saved, Michigan time (empty if unknown); the OpMode's name on the Driver Station ends with it. */
    public static final String SAVED = "11-11|12:00AM";

    /** Registered robot commands this Auto uses; checked when the OpMode initialises. */
    public static final String[] COMMANDS = {"LaunchAll", "PickFlower", "SpinUp", "StreamOff", "StreamOn", "SweepRow"};

    /** Registered robot triggers this Auto uses; checked when the OpMode initialises. */
    public static final String[] TRIGGERS = {"Empty", "LeftCellUp", "RightCellUp"};

    /** The alliance the Auto was drawn for ("RED" or "BLUE"); the other alliance runs it rotated half a turn about the field centre. */
    public static final String DRAWN_FOR = "RED";

    /** What the drive team may change during INIT, on gamepad 1's D-pad; nothing changed, the Auto runs as drawn. */
    public static final AutoOption[] OPTIONS = {};

    /** Where the robot starts, for the given alliance. */
    public static Pose startPose(boolean rotated) {
        return poses(rotated).of(55.6, 7.7, 90);
    }

    private static PoseFactory poses(boolean rotated) {
        return rotated ? PoseFactory.degrees().mirrorAroundPoint(70.75, 70.75) : PoseFactory.degrees();
    }

    /** Builds the whole Auto. Call once, at init; schedule the result at start. */
    public static Command build(AutoKit kit, boolean rotated) {
        PoseFactory p = poses(rotated);

        // Named points (x, y in inches, heading in degrees, Pedro field frame).
        Pose rightStart = p.of(55.6, 7.7, 90);
        Pose rowApproach = p.of(35.4, 120, 90);
        Pose scoringFlowerStaging = p.of(47.2, 119.3, 90);
        Pose wallFlowerStaging = p.of(23.1, 47.2, 180);
        Pose laneRight = p.of(26, 40, 180);
        Pose gardenRowStart = p.of(22, 8, 180);
        Pose rightLaunchCorner = p.of(30.2, 10.7, 180);
        Pose rightPark = p.of(14.5, 95.7, 0);

        // Other poses the paths need (control points, unnamed endpoints).
        Pose toRowApproachControl1 = p.of(62, 30, 0);
        Pose toRowApproachControl2 = p.of(66, 80, 0);
        Pose toRowApproachControl3 = p.of(66, 118, 0);
        Pose toRowApproachControl4 = p.of(44, 116, 0);
        Pose scoringFlowerStagingToWallFlowerStagingControl1 = p.of(26, 108, 0);
        Pose scoringFlowerStagingToWallFlowerStagingControl2 = p.of(24, 70, 0);
        Pose scoringFlowerStagingToWallFlowerStagingSegment1Start = p.of(23.1, 47.2, 90);
        Pose laneRightParkControl1 = p.of(24, 60, 0);
        Pose toGardenRowStartControl1 = p.of(32, 20, 0);
        Pose toGardenRowStartControl2 = p.of(36, 8, 0);
        Pose gardenRowStartParkControl1 = p.of(24, 60, 0);
        Pose toRightParkControl1 = p.of(26, 55, 0);
        Pose toRightParkSegment1Start = p.of(14.5, 95.7, 180);
        Pose toRightParkSegment1End = p.of(14.5, 95.7, 180);
        Pose toRightParkSegment2Start = p.of(14.5, 95.7, 180);

        // Paths, written as the stock Visualizer export writes them.
        Path toRowApproach = Paths.curve(rightStart, toRowApproachControl1, toRowApproachControl2, toRowApproachControl3, toRowApproachControl4, rowApproach).constant(rowApproach);
        Path rowApproachPark = Paths.line(rowApproach, rightPark).linear(rowApproach, rightPark);
        Path rowEndToScoringFlowerStaging = Paths.line(rowApproach, scoringFlowerStaging).constant(scoringFlowerStaging);
        Path scoringFlowerStagingPark = Paths.line(scoringFlowerStaging, rightPark).linear(scoringFlowerStaging, rightPark);
        Path scoringFlowerStagingToWallFlowerStaging = Paths.curve(scoringFlowerStaging, scoringFlowerStagingToWallFlowerStagingControl1, scoringFlowerStagingToWallFlowerStagingControl2, wallFlowerStaging).heading(Interpolator.piecewise().until(0.5, Interpolator.linear(scoringFlowerStagingToWallFlowerStagingSegment1Start, wallFlowerStaging)).until(1, Interpolator.linear(wallFlowerStaging, wallFlowerStaging)));
        Path wallFlowerStagingPark = Paths.line(wallFlowerStaging, rightPark).linear(wallFlowerStaging, rightPark);
        Path toLaneRight = Paths.line(wallFlowerStaging, laneRight).constant(laneRight);
        Path laneRightPark = Paths.curve(laneRight, laneRightParkControl1, rightPark).linear(laneRight, rightPark);
        Path toGardenRowStart = Paths.curve(laneRight, toGardenRowStartControl1, toGardenRowStartControl2, gardenRowStart).constant(gardenRowStart);
        Path gardenRowStartPark = Paths.curve(gardenRowStart, gardenRowStartParkControl1, rightPark).linear(gardenRowStart, rightPark);
        Path toRightLaunchCorner = Paths.line(gardenRowStart, rightLaunchCorner).constant(rightLaunchCorner);
        Path toRightPark = Paths.curve(rightLaunchCorner, toRightParkControl1, rightPark).heading(Interpolator.piecewise().until(0.4, Interpolator.linear(toRightParkSegment1Start, toRightParkSegment1End)).until(1, Interpolator.linear(toRightParkSegment2Start, rightPark)));

        return kit.sequence(
                kit.guarded("Auto", toRightPark, 2.7,
                        kit.command("SpinUp"),
                        kit.command("LaunchAll"),
                        kit.path("to ROW_APPROACH", toRowApproach, 3.2, rowApproachPark, 1.7),
                        kit.command("SweepRow", 4),
                        kit.firstOf("Wait for the LEFT CELL",
                                kit.when("LeftCellUp"),
                                kit.afterMs(3000)),
                        kit.command("StreamOn"),
                        kit.path("ROW_END to SCORING_FLOWER_STAGING", rowEndToScoringFlowerStaging, 1, scoringFlowerStagingPark, 1.8),
                        kit.command("PickFlower", 4.5),
                        kit.firstOf("Wait until empty",
                                kit.when("Empty"),
                                kit.afterMs(4000)),
                        kit.command("StreamOff"),
                        kit.path("SCORING_FLOWER_STAGING to WALL_FLOWER_STAGING", scoringFlowerStagingToWallFlowerStaging, 2.6, wallFlowerStagingPark, 2),
                        kit.command("PickFlower", 4.5),
                        kit.path("to LANE_RIGHT", toLaneRight, 0.8, laneRightPark, 2.2),
                        kit.firstOf("Wait for the RIGHT CELL",
                                kit.when("RightCellUp"),
                                kit.afterMs(2500)),
                        kit.command("StreamOn"),
                        kit.firstOf("Wait until empty",
                                kit.when("Empty"),
                                kit.afterMs(4000)),
                        kit.path("to GARDEN_ROW_START", toGardenRowStart, 1.8, gardenRowStartPark, 2.7),
                        kit.command("SweepRow", 4),
                        kit.path("to RIGHT_LAUNCH_CORNER", toRightLaunchCorner, 0.9),
                        kit.firstOf("Wait until the last piece is out",
                                kit.when("Empty"),
                                kit.afterMs(4000)),
                        kit.path("to RIGHT_PARK", toRightPark, 2.7)));
    }
}
